items.script:
(blockcontext, pageContext, item) => {
    let staticBreadcrumbData = [{
        "label": "Major Incident Management",
        "href": "now/sow-admin/major-incident-management"
    }, {
        "label": "Configure major incident trigger rules",
        "href": "now/sow-admin/configure-mi-trigger-rules"
    }];
    let triggerRuleSysId = pageContext.props.triggerRuleSysId;
    var lastItem =  {
        "label": triggerRuleSysId == -1  ? "New trigger rule" : blockcontext.triggerRuleName,
        "href": "now/sow-admin/mi-trigger-rule/" + triggerRuleSysId
    };
    staticBreadcrumbData.push(lastItem)
    return staticBreadcrumbData;
}
